-- =============================================================================
-- 060 · Estratégia da 2Siglas: ciclo "Nov 2026 – Jan 2027"
-- A partir do "2Siglas Guia de Estratégia de Marca" (Notion), nas 9 secções da aba Estratégia:
--  · 3 frentes/objetivos: Cibersegurança · Online B2C · Obrigatórias B2B
--  · concorrentes, palavras-chave e desempenho de publicações (13 resultados)
--  · posicionamento (10 campos), storytelling (6 narrativas), jornadas (João, Ana, Cátia)
--  · funil com 12 etapas (4 por frente), analytics/SEO/GEO/SMO/SEA, pontos de controlo e decisões
-- Personas ligadas pelo nome (João, Ana, Nuno, Cátia, Hélder, Marta, Ricardo, Tiago) da migração 054.
-- Idempotente: não cria o ciclo se a 2Siglas já tiver um com este nome. Requer 052–057.
-- =============================================================================

do $mig$
declare
    v_marca uuid;
    v_dados text;
    p record;
begin
    select id into v_marca from public.marketing_marcas where lower(nome) = '2siglas' limit 1;
    if v_marca is null then
        raise notice '060: marca 2Siglas não existe, nada a fazer';
        return;
    end if;
    if exists (select 1 from public.marketing_ciclos where marca_id = v_marca and nome = 'Nov 2026 – Jan 2027') then
        raise notice '060: ciclo já existe, nada a fazer';
        return;
    end if;

    v_dados := $j${"objetivos":{"lista":[{"frente":"Cibersegurança","negocio":"Entrar no mercado de Cibersegurança com formação online (ciber-higiene para colaboradores de PME, B2B, com turma aberta também para B2C).","comunicacao":"Posicionar a 2Siglas como a entidade formadora regional de referência em ciber-higiene certificada: \"o EPI digital da sua equipa\".","kpi":"Leads qualificados de cibersegurança (pedidos de proposta + inscrições na sessão online gratuita)","investimento":"≈ 40% do orçamento pago do trimestre (referência: 600–900 €) + produção de 1 curso-âncora, 1 guia gratuito e 1 sessão online de 45 min","meta":"50 leads · 3 empresas-piloto em turma fechada · 40 inscrições em turma aberta online","prazo":"Lançamento a 30 nov 2026 (Dia Internacional da Segurança Informática) · avaliação a 31 jan 2027"},{"frente":"Online B2C","negocio":"Vender formações online B2C em Desenvolvimento Pessoal (090) e nas restantes áreas (Formação de Formadores, Saúde, Desporto, Informática na ótica do utilizador, Marketing).","comunicacao":"Tornar a oferta online fácil de encontrar, perceber e comprar sem telefonema: preço visível, certificado claro, checkout em 3 passos.","kpi":"Inscrições online pagas (checkout concluído)","investimento":"≈ 35% (referência: 500–800 €), sobretudo Meta Ads","meta":"80 inscrições pagas · conversão das páginas de curso ≥ 2% · 30 vales-formação de Natal","prazo":"Black Friday 27 nov · Vale-formação 1–20 dez · \"Ano novo, competências novas\" 2–31 jan"},{"frente":"Obrigatórias B2B","negocio":"Aumentar o volume de vendas das formações obrigatórias e à medida para empresas, com contratação por formando (turma aberta) ou por equipa (turma fechada/in-company).","comunicacao":"Simplificar a decisão: mostrar as duas modalidades lado a lado e o custo de não cumprir as 40 horas anuais (crédito de horas que vira passivo).","kpi":"Propostas aceites (por formando + por equipa) e faturação B2B","investimento":"≈ 25% (referência: 400–600 €) em Google Ads + e-mail marketing (custo interno)","meta":"+20% de faturação B2B face a nov–jan anterior · 12 propostas aceites, das quais ≥ 4 por equipa","prazo":"Fecho das 40 h de 2026 até 18 dez · Planos de formação 2027 fechados até 31 jan"}]},"mercado":{"concorrentes":[{"marca":"Traininghouse Cursos e Formação"},{"marca":"FormAlgarve - Cursos e Formação"},{"marca":"Planeta Informático - Formação e Consultoria"},{"marca":"MasterD"}]},"pesquisa":{"palavras":[{"tipo":"Genéricas","personas":[]},{"tipo":"Segmentadas","personas":["@ana"],"termos":"Como criar plano de formação interno","fonte":"https://answerthepublic.com/","periodo":"6-10 de novembro 2026"},{"tipo":"Segmentadas","personas":["@cátia"],"termos":"FORMAÇÃO FINANCIADA A 100%","fonte":"Concorrência","periodo":"6-10 de novembro 2026"},{"tipo":"Específicas","personas":["@ana","@ricardo"],"termos":"Alterações climáticas impacto agricultura portuguesa","fonte":"https://answerthepublic.com/","periodo":"6-10 de novembro 2026"},{"tipo":"Específicas","personas":["@cátia"],"termos":"Como escolher entidade formadora certificada","fonte":"https://answerthepublic.com/","periodo":"6-10 de novembro 2026"},{"tipo":"Específicas","personas":["@ricardo"],"termos":"formação aplicação pesticidas","fonte":"https://answerthepublic.com/","periodo":"6-10 de novembro 2026"}],"desempenho":[{"canal":"Instagram","metrica":"Alcance","resultado":215,"tema":"Cibersegurança","formato":"Carrossel","dia_semana":"Quinta","data":"2026-11-05","horario":"10h00"},{"canal":"Instagram","metrica":"Visualizações","resultado":323,"tema":"Cibersegurança","formato":"Carrossel","dia_semana":"Quinta","data":"2026-11-05","horario":"10h00"},{"canal":"Instagram","metrica":"Visualizadores","resultado":218,"tema":"Cibersegurança","formato":"Carrossel","dia_semana":"Quinta","data":"2026-11-05","horario":"10h00"},{"canal":"Facebook","metrica":"Visualizações","resultado":136,"tema":"Os primeiros passos na arboricultura","formato":"Único","dia_semana":"Terça-feira","data":"2026-10-20","horario":"17:32"},{"canal":"Facebook","metrica":"Visualizadores","resultado":100,"tema":"Os primeiros passos na arboricultura","formato":"Único","dia_semana":"Terça-feira","data":"2026-10-20","horario":"17:32"},{"canal":"Facebook","metrica":"Visualizações","resultado":91,"tema":"Acessibilidade não é um detalhe.","formato":"Carrossel","dia_semana":"Quarta-feira","data":"2026-10-14","horario":"17:00"},{"canal":"Facebook","metrica":"Visualizadores","resultado":75,"tema":"Acessibilidade não é um detalhe.","formato":"Carrossel","dia_semana":"Quarta-feira","data":"2026-10-14","horario":"17:00"},{"canal":"Facebook","metrica":"Visualizações","resultado":321,"tema":"A importância da cidadania","formato":"Único","dia_semana":"Segunda-feira","data":"2026-10-05","horario":"10:00"},{"canal":"Facebook","metrica":"Visualizadores","resultado":227,"tema":"A importância da cidadania","formato":"Único","dia_semana":"Segunda-feira","data":"2026-10-05","horario":"10:00"},{"canal":"Facebook","metrica":"Interações","resultado":5,"tema":"A importância da cidadania","formato":"Único","dia_semana":"Segunda-feira","data":"2026-10-05","horario":"10:00"},{"canal":"Facebook","metrica":"Visualizações","resultado":269,"tema":"Sustentabilidade","formato":"Carrossel","dia_semana":"Sábado","data":"2026-09-05","horario":"11:30"},{"canal":"Facebook","metrica":"Visualizadores","resultado":169,"tema":"Sustentabilidade","formato":"Carrossel","dia_semana":"Sábado","data":"2026-09-05","horario":"11:30"},{"canal":"Facebook","metrica":"Interações","resultado":4,"tema":"Sustentabilidade","formato":"Carrossel","dia_semana":"Sábado","data":"2026-09-05","horario":"11:30"}]},"curadoria":{"referencias":[]},"posicionamento":{"campos":[{"campo":"Proposta única de valor","estrategia":"Formação certificada DGERT, prática e próxima, que protege pessoas e negócios no terreno, na sala e agora também no digital, contratável por formando ou por equipa.","periodo":"1 nov 2026 – 31 jan 2027","esperado":"A mesma mensagem em todos os canais; a 2Siglas passa a ser reconhecida para além da agricultura e da HST"},{"campo":"Arquétipo primário (dominante)","estrategia":"Sábio-Mentor (60%). Explica com clareza o que a lei exige (40 h anuais, NIS2/DL 125/2025, ciber-higiene) sem alarmismo. Conteúdos: guias, artigos, FAQs, \"a lei em 60 segundos\".","periodo":"nov – jan","esperado":"Autoridade: mais pesquisas orgânicas, guardados e partilhas de conteúdos educativos"},{"campo":"Arquétipo complementar","estrategia":"Cuidador (25%). \"Cuidamos da segurança de quem trabalha, física e digital.\" Apoio na escolha do curso, acompanhamento pós-formação, linguagem próxima no Instagram/Facebook e no WhatsApp.","periodo":"nov – jan","esperado":"Confiança: mais mensagens diretas e pedidos de esclarecimento, menos objeções de preço"},{"campo":"Arquétipo de suporte","estrategia":"Criativo (15%). Inovação pedagógica online: quiz de ciber-higiene, mini-aulas em vídeo, simulação de phishing em sessão, certificados partilháveis no LinkedIn.","periodo":"nov – jan","esperado":"Diferenciação face ao e-learning genérico; mais interação nos Reels/quizzes"},{"campo":"Diferenciação da concorrência","estrategia":"Contra plataformas genéricas de e-learning: certificado de entidade certificada DGERT, válido para as 40 h e registado no SIGO, com formador real. Contra grandes consultoras de NIS2: linguagem e preço de PME, foco em todos os colaboradores (ciber-higiene) e não em especialistas de TI. Contra outras entidades formadoras: quase 20 anos (20 anos a 28 mar 2027), proximidade no Algarve e flexibilidade por formando/por equipa.","periodo":"nov – jan","esperado":"Argumentário único usado em propostas, páginas de curso e anúncios"},{"campo":"Ticket médio","estrategia":"Apurar o valor real de 2026 até 15 nov (B2C online · B2B por formando · B2B por equipa). Regra proposta para o preço por equipa: a partir do 6.º formando, a turma fechada fica mais barata do que a soma das inscrições individuais. Venda cruzada: obrigatória + ciber-higiene no mesmo plano anual.","periodo":"Linha de base: 2026 · Medição: jan 2027","esperado":"Ticket médio B2B +15% através de pacotes por equipa e venda cruzada"},{"campo":"Especificações / restrições","estrategia":"Comunicar como \"certificada\" só a formação enquadrada em área DGERT certificada (ciber-higiene → área 482, a confirmar). A 2Siglas forma, mas não certifica a conformidade NIS2: nunca prometer \"fica conforme\". Formador de ciber com credenciais verificáveis. PT-PT, sem excesso de emojis e sem urgência artificial. Recolha de leads conforme o RGPD. Checkout online testado antes de 27 nov.","periodo":"Contínuo","esperado":"Zero ruído reputacional; mensagens alinhadas com o Brand Personality"},{"campo":"Persona principal","estrategia":"João: empresário de PME (40–58 anos), decisor tanto das obrigatórias como da cibersegurança. Secundárias B2B: Ana (RH em média/grande empresa) e Nuno (SST). B2C: Cátia (independente), Hélder (futuro formador/CCP), Marta (treinadora).","periodo":"nov – jan","esperado":"Conteúdos e anúncios segmentados por persona, com mensagem diferente para cada uma"},{"campo":"Declaração de posicionamento","estrategia":"Para empresários de PME que precisam de cumprir a formação obrigatória e proteger o negócio sem perder tempo nem dinheiro em formações teóricas, a 2Siglas é a entidade formadora certificada DGERT que prepara equipas para trabalhar com segurança, no terreno e no digital, contratável por formando ou por equipa. Ao contrário das plataformas genéricas de e-learning e das grandes consultoras, tem quase 20 anos de formação prática certificada e fala a linguagem das PME.","periodo":"nov – jan","esperado":"Declaração usada como base do site, do LinkedIn e das propostas comerciais"},{"campo":"Hipótese de melhoria","estrategia":"Se implementarmos uma sessão online gratuita de 45 min (\"Ciber-higiene para PME: o que a sua equipa precisa de saber\") com um guia para descarregar, esperamos gerar 50 leads B2B e 3 turmas-piloto, porque o novo Regime Jurídico da Cibersegurança (DL 125/2025, em vigor desde abril de 2026) pôs o tema na agenda dos gestores e dos fornecedores de entidades abrangidas, e a 2Siglas já tem a confiança das PME através da formação obrigatória.","periodo":"30 nov 2026 – 31 jan 2027","esperado":"Validar (ou não) a cibersegurança como nova linha de negócio antes de investir em mais cursos"}]},"storytelling":{"narrativas":[{"narrativa":"Metáfora central","micro":"B2B: \"O EPI digital\". O capacete protege no terreno, a ciber-higiene protege no ecrã: a segurança é a mesma, só muda o risco. B2C: \"A caixa de ferramentas\". Cada certificado é uma ferramenta nova para aceitar mais clientes ou mudar de função.","personas":["@joão","@ana","@nuno","@cátia","@hélder","@marta"],"temas":"Carrossel \"O EPI digital da sua equipa\" · \"5 ferramentas que pode juntar ao seu CV em 2027\" · Artigo de lançamento ciber","periodo":"Lançamento a 30 nov · reforço em jan","esperado":"Associação espontânea da 2Siglas à \"segurança 360°\" (física + digital)"},{"narrativa":"Empatia & memória","micro":"B2B: o e-mail da \"fatura em atraso\" que alguém da equipa quase abriu; a corrida de dezembro para cumprir as 40 horas. B2C: a resolução de Ano Novo que ficou na gaveta; o certificado que faltou para aquela oportunidade.","personas":["@joão","@ana","@cátia","@hélder"],"temas":"Burlas de Black Friday e Natal (dicas para empresas e particulares) · \"Ainda vai a tempo das 40 horas de 2026\" · \"Este ano é o ano\" (jan)","periodo":"nov (Black Friday) · dez (fecho de ano) · jan (Ano Novo)","esperado":"Identificação imediata: mais comentários, partilhas e mensagens diretas"},{"narrativa":"Vilão / obstáculo","micro":"B2B: o clique errado (phishing, fraude do falso fornecedor), a gestão de várias entidades formadoras e o crédito de horas acumulado que se transforma em passivo. B2C: a falta de tempo e as formações teóricas que não servem para o dia a dia. Sem alarmismo: vilões concretos, nunca o medo como argumento.","personas":["@joão","@ana","@nuno","@cátia","@marta"],"temas":"\"3 sinais de que um e-mail é falso\" · \"O que acontece às horas de formação que não deu?\" · \"Formação online ao seu ritmo, com formador real\"","periodo":"nov – dez","esperado":"Mais pedidos de proposta vindos de conteúdos educativos (e não só de anúncios)"},{"narrativa":"Jornada do herói","micro":"O cliente é o herói que protege a equipa ou o próprio futuro; a 2Siglas é o mentor. B2B: diagnóstico rápido → plano (por formando ou por equipa) → formação prática → certificados e registo para o Relatório Único. B2C: escolhe o curso → aprende online ao seu ritmo → recebe o certificado → aplica no trabalho.","personas":["@joão","@ana","@cátia","@hélder"],"temas":"\"Como funciona: do diagnóstico ao certificado\" (carrossel 6 slides) · Bastidores da preparação do curso de ciber · Reel \"Um dia de formação online\"","periodo":"dez – jan","esperado":"Menos fricção na decisão: ciclo de venda B2B mais curto"},{"narrativa":"Transformação final","micro":"B2B: equipa com as 40 h cumpridas e os certificados emitidos; colaboradores que reconhecem uma tentativa de phishing (medido por quiz antes e depois). B2C: certificado no CV/LinkedIn e um cliente ou função nova.","personas":["@joão","@ana","@nuno","@cátia","@marta","@hélder"],"temas":"Resultado do quiz das turmas-piloto (\"antes 4/10, depois 9/10\", com dados reais) · Testemunhos de formandos online","periodo":"jan","esperado":"Prova concreta e verificável para usar em propostas e anúncios"},{"narrativa":"Reconhecimento (autoridade)","micro":"Entidade certificada DGERT desde 2013; contagem decrescente para os 20 anos (28 mar 2027); número real de formandos e empresas formadas (apurar); testemunhos das empresas-piloto de ciber; parceiros institucionais (DGERT, CCDR Algarve, IPDJ).","personas":["@joão","@ana","@nuno","@ricardo","@tiago","@cátia","@marta","@hélder"],"temas":"Teaser \"Rumo aos 20 anos\" · \"Em números: 2Siglas 2007–2026\" (infográfico) · Testemunhos em vídeo curto","periodo":"jan (arranque da campanha dos 20 anos)","esperado":"Reforço da credibilidade para sustentar a entrada numa área nova (ciber)"}]},"funil":{"jornadas":[{"persona":"@joão","descobre":"LinkedIn/Facebook (\"O EPI digital\") ou Google (\"formação cibersegurança empresas\")","aprofunda":"Artigo do site, guia gratuito e sessão online","decide":"Proposta com as duas modalidades lado a lado e uma chamada de 15 min","mantem":"Plano anual das 40 h gerido pela 2Siglas"},{"persona":"@ana","descobre":"LinkedIn ou newsletter","aprofunda":"Página \"Por formando ou por equipa?\" (tabela comparativa)","decide":"Proposta e referência de cliente","mantem":"Interlocutor único e relatório anual de formação (Anexo C)"},{"persona":"@cátia","descobre":"Instagram (Reel/carrossel) ou anúncio de Black Friday/Ano Novo","aprofunda":"Página do curso (programa, certificado, FAQ, preço)","decide":"Testemunho, preço claro e checkout simples","mantem":"Desconto no próximo curso e newsletter"}],"etapas":[{"etapa":"Descoberta (topo)","frente":"Cibersegurança","personas":["@joão","@ana","@nuno"],"precisa":"Perceber que tem um problema ou oportunidade","canais":"LinkedIn, Facebook, Google (SEO)","formatos":"Carrossel \"EPI digital\", artigo do site, Reel \"3 sinais de phishing\"","pilares":"Educação · Segurança digital","cta":"\"Saiba mais\" / \"Guarde este post\"","pct":15,"frequencia":"2 por semana","periodo":"23 nov – 31 jan","metrica":"Alcance, guardados, tráfego para a landing","esperado":"5.000 pessoas alcançadas no segmento empresas"},{"etapa":"Consideração (meio)","frente":"Cibersegurança","personas":["@joão","@ana"],"precisa":"Comparar soluções e confiar na marca","canais":"Site (landing), e-mail, sessão online","formatos":"Guia para descarregar, sessão online de 45 min, FAQ NIS2/ciber-higiene","pilares":"Autoridade · Sábio","cta":"\"Descarregue o guia\" / \"Inscreva-se na sessão gratuita\"","pct":10,"frequencia":"1 por semana + 1 sessão por mês","periodo":"30 nov – 31 jan","metrica":"Downloads, inscrições na sessão","esperado":"50 leads"},{"etapa":"Decisão (fundo)","frente":"Cibersegurança","personas":["@joão","@ana"],"precisa":"Ter segurança para avançar","canais":"E-mail, telefone, WhatsApp","formatos":"Proposta com piloto, caso das empresas-piloto, quiz antes/depois","pilares":"Prova · Transformação","cta":"\"Peça uma proposta para a sua equipa\"","pct":7,"frequencia":"Sequência de 3 e-mails após download","periodo":"dez – jan","metrica":"Propostas enviadas e aceites","esperado":"3 empresas-piloto"},{"etapa":"Fidelização","frente":"Cibersegurança","personas":[],"precisa":"Tirar partido e recomendar (empresas-piloto)","canais":"E-mail, LinkedIn","formatos":"Relatório de resultados, certificado partilhável, pedido de testemunho","pilares":"Cuidador · Reconhecimento","cta":"\"Partilhe o seu certificado\" / \"Recomende-nos\"","pct":3,"frequencia":"1 contacto pós-formação","periodo":"jan","metrica":"Testemunhos recolhidos, NPS","esperado":"3 testemunhos utilizáveis"},{"etapa":"Descoberta (topo)","frente":"Online B2C","personas":["@cátia","@hélder","@marta"],"precisa":"Perceber que tem um problema ou oportunidade","canais":"Instagram, Facebook, Meta Ads","formatos":"Reels, carrosséis \"caixa de ferramentas\", posts de Black Friday/Ano Novo","pilares":"Desenvolvimento pessoal · Carreira","cta":"\"Siga-nos\" / \"Descubra os cursos online\"","pct":14,"frequencia":"3 por semana","periodo":"9 nov – 31 jan","metrica":"Alcance, visitas às páginas de curso","esperado":"10.000 pessoas alcançadas"},{"etapa":"Consideração (meio)","frente":"Online B2C","personas":["@cátia","@hélder"],"precisa":"Comparar soluções e confiar na marca","canais":"Site, Instagram (Stories/destaques), WhatsApp","formatos":"Página de curso com tabela-resumo, FAQ, testemunho, mini-aula grátis","pilares":"Prova social · Clareza","cta":"\"Veja o programa\" / \"Fale connosco no WhatsApp\"","pct":10,"frequencia":"2 por semana","periodo":"nov – jan","metrica"